add_filter( 'cron_schedules', 'perfectpixel_digest_schedule' );
add_action( 'init', 'perfectpixel_digest_schedule_event' );
add_action( 'perfectpixel_orders_digest', 'perfectpixel_send_orders_digest' );

function perfectpixel_digest_interval() {
	return max( 1, (int) '{{digest_hours}}' ) * HOUR_IN_SECONDS;
}

function perfectpixel_digest_schedule( $schedules ) {
	$schedules['perfectpixel_digest'] = array(
		'interval' => perfectpixel_digest_interval(),
		'display'  => 'Σύνοψη παραγγελιών',
	);
	return $schedules;
}

function perfectpixel_digest_schedule_event() {
	if ( ! wp_next_scheduled( 'perfectpixel_orders_digest' ) ) {
		wp_schedule_event( time() + perfectpixel_digest_interval(), 'perfectpixel_digest', 'perfectpixel_orders_digest' );
	}
}

function perfectpixel_send_orders_digest() {
	$orders = wc_get_orders(
		array(
			'date_created' => '>' . ( time() - perfectpixel_digest_interval() ),
			'status'       => array_keys( wc_get_is_paid_statuses() ) ? wc_get_is_paid_statuses() : array( 'processing', 'completed' ),
			'limit'        => 200,
			'type'         => 'shop_order',
		)
	);
	if ( ! $orders ) {
		return;
	}
	$total = 0.0;
	$rows  = '';
	foreach ( $orders as $order ) {
		$total += (float) $order->get_total();
		$rows  .= sprintf(
			'<tr><td><a href="%s">#%s</a></td><td>%s</td><td>%s</td></tr>',
			esc_url( $order->get_edit_order_url() ),
			esc_html( $order->get_order_number() ),
			esc_html( wc_get_order_status_name( $order->get_status() ) ),
			wp_kses_post( $order->get_formatted_order_total() )
		);
	}
	$subject   = sprintf( 'Σύνοψη: %d νέες παραγγελίες, %s', count( $orders ), wp_strip_all_tags( wc_price( $total ) ) );
	$body      = '<table cellpadding="6" style="border-collapse:collapse;width:100%"><tr><th align="left">Παραγγελία</th><th align="left">Κατάσταση</th><th align="left">Σύνολο</th></tr>' . $rows . '</table>';
	$recipient = sanitize_email( '{{digest_recipient}}' );
	$mailer    = WC()->mailer();
	$mailer->send( $recipient ? $recipient : get_option( 'admin_email' ), $subject, $mailer->wrap_message( $subject, $body ) );
}
